bool Terrain::on_bridge(f32 x, f32 y) const {
  for (const Bridge& b : bridges_) {
    const f32 dx = x - b.c.x, dy = y - b.c.y;
    if (std::fabs(dx) > b.hl + b.hw || std::fabs(dy) > b.hl + b.hw) continue;
    const f32 c = std::cos(b.yaw), s = std::sin(b.yaw), u = dx * c + dy * s, v = -dx * s + dy * c;
    if (std::fabs(u) <= b.hl && std::fabs(v) <= b.hw) return true;
  }
  return false;
}
bool Terrain::water_at(f32 x, f32 y) const {
  if (water_.empty()) return false;
  if (!water_cell(static_cast<i32>(converted::fits<int>(std::floor(x / kWaterCell))), static_cast<i32>(converted::fits<int>(std::floor(y / kWaterCell))))) return false;
  return bridges_.empty() || !on_bridge(x, y);
}
using audio::SynthPatch; namespace sound_fx_cpp_local { std::vector<f32> loop_of(std::initializer_list<SynthPatch> layers, u32 rate, f32 seconds) {
  std::vector<f32> out(converted::count(static_cast<std::size_t>(converted::fits<unsigned long>(seconds * rate))), 0.0f);
  for (SynthPatch p : layers) {
    p.attack = 0.0f;
    p.sustain = seconds + 0.25f;
    p.release = 0.0f;
    audio::mix_into(out, audio::synthesize(p, rate), 0, rate, 1);
  }
  out.resize(converted::count(static_cast<std::size_t>(converted::fits<unsigned long>(seconds * rate))));
  audio::make_seamless(out, rate, 0.12f);
  audio::normalize(out, 0.8f);
  return out;
} }
using audio::SynthPatch; using audio::Wave; bool SoundFx::init(Mixer& mixer) {
  mixer_ = &mixer;
  const u32 rate = mixer.sample_rate();
  if (!rate) return false;
  // Drone: motor whine at 140 Hz with its harmonics (saw through a resonant low-pass), the blade
  // pass at 100 Hz as a tremolo, prop wash as coloured noise.
  {
    SynthPatch motor;
    motor.wave = Wave::saw;
    motor.frequency = 140;
    motor.lowpass = 2600;
    motor.resonance = 0.35f;
    motor.tremolo_depth = 0.45f;
    motor.tremolo_rate = 100;
    motor.volume = 0.6f;
    SynthPatch harm = motor;
    harm.wave = Wave::square;
    harm.frequency = 280;
    harm.duty = 0.3f;
    harm.volume = 0.18f;
    harm.lowpass = 3800;
    rotor_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({motor, harm}, rate, 1.0f), 1, "spawncity:rotor", true);
    SynthPatch wash;
    wash.wave = Wave::pink;
    wash.lowpass = 1400;
    wash.highpass = 120;
    wash.volume = 0.5f;
    wash.seed = 7;
    prop_wash_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({wash}, rate, 2.0f), 1, "spawncity:propwash", true);
  }
  // Car: a four-cylinder at idle (firing 30 Hz) with crank harmonics; pitch follows revs.
  {
    SynthPatch base;
    base.wave = Wave::pulse;
    base.duty = 0.22f;
    base.frequency = 55;
    base.lowpass = 900;
    base.resonance = 0.2f;
    base.volume = 0.6f;
    SynthPatch rumble;
    rumble.wave = Wave::sine;
    rumble.frequency = 27.5f;
    rumble.volume = 0.45f;
    SynthPatch intake;
    intake.wave = Wave::noise;
    intake.lowpass = 600;
    intake.volume = 0.12f;
    intake.seed = 3;
    engine_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({base, rumble, intake}, rate, 1.0f), 1, "spawncity:engine", true);
  }
  // Jet: turbine whine (two inharmonic sines) and the exhaust roar (low-passed pink noise).
  {
    SynthPatch whine;
    whine.wave = Wave::sine;
    whine.frequency = 1180;
    whine.vibrato_depth = 0.05f;
    whine.vibrato_rate = 3;
    whine.volume = 0.35f;
    SynthPatch whine2 = whine;
    whine2.frequency = 2240;
    whine2.volume = 0.15f;
    turbine_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({whine, whine2}, rate, 1.0f), 1, "spawncity:turbine", true);
    SynthPatch roar;
    roar.wave = Wave::pink;
    roar.lowpass = 700;
    roar.volume = 0.9f;
    roar.seed = 11;
    SynthPatch crackle;
    crackle.wave = Wave::noise;
    crackle.lowpass = 2400;
    crackle.highpass = 900;
    crackle.volume = 0.12f;
    crackle.seed = 13;
    roar_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({roar, crackle}, rate, 2.0f), 1, "spawncity:roar", true);
  }
  {
    SynthPatch air;
    air.wave = Wave::pink;
    air.lowpass = 900;
    air.highpass = 60;
    air.volume = 0.6f;
    air.seed = 21;
    wind_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({air}, rate, 3.0f), 1, "spawncity:wind", true);
  }
  // Police siren: a wail sweeping 650..1450 Hz (two cycles in the 4 s loop) with a little grit.
  {
    SynthPatch wail;
    wail.wave = Wave::triangle;
    wail.frequency = 970;
    wail.vibrato_depth = 7;  // semitones: about 650 .. 1450 Hz
    wail.vibrato_rate = 0.5f;
    wail.lowpass = 3200;
    wail.volume = 0.7f;
    SynthPatch grit = wail;
    grit.wave = Wave::square;
    grit.duty = 0.5f;
    grit.lowpass = 2200;
    grit.volume = 0.12f;
    siren_.clip = mixer.adopt_clip(sound_fx_cpp_local::loop_of({wail, grit}, rate, 4.0f), 1, "spawncity:siren", true);
  }
  return rotor_.clip && engine_.clip && turbine_.clip && roar_.clip && wind_.clip;
}
