namespace city_stream_cpp_local { void put_footprint(FootprintStream& fs, const MapFeatures::Building& b, Vec2 c, std::vector<Vec2>& thin) {
  fs.begin(b.seed, b.base, b.top, c.x, c.y);
  for (const auto& ring : b.rings) {
    if (ring.size() <= 96) { fs.ring(ring.data(), static_cast<u32>(ring.size())); continue; }
    const std::size_t step = (ring.size() + 95) / 96;
    thin.clear();
    for (std::size_t k = 0; k < ring.size(); k += step) thin.push_back(converted::at(ring, k));
    fs.ring(thin.data(), static_cast<u32>(thin.size()));
  }
} }
void CityStream::remove(Tile& t) {
  if (r_) {
    auto drop = [&](const std::vector<u32>& list) { for (u32 id : list) r_->remove(id); };
    drop(t.meshes);
    drop(t.lay_meshes);
    drop(t.old_lay);
  }
  auto cancel = [](u32& job) { if (job) { jobs::cancel(job); job = 0; } };
  cancel(t.tile_job);
  cancel(t.build_job);
  cancel(t.cell_job);
  t.cell_ids.clear();
  t.dirty_cells.clear();
  t.job_cells.clear();
  if (r_) for (auto& [c, ids] : t.cell_old) for (u32 id : ids) r_->remove(id);
  t.cell_old.clear();
  t.want_cells.clear();
  t.cell_uploading = false;
  t.meshes.clear();
  t.lay_meshes.clear();
  t.old_lay.clear();
  near_.dirty = true;  // the collision set may hold this tile's buildings
  if (t.prepared) ++furniture_serial_;
  terrain_.remove_tints(t.key.hash());
  terrain_.remove_corridors(t.key.hash());
  if (world_ && t.body.valid() && world_->body_valid(t.body)) world_->destroy_body(t.body);
  t.body = {};
  if (world_ && t.old_body.valid() && world_->body_valid(t.old_body)) world_->destroy_body(t.old_body);  // M3 life
  t.old_body = {};
  for (Lane& l : lanes_)
    if (l.tile == t.key.hash()) l.alive = false;
}
void CityStream::request_around(Vec3 focus, i32 ring) {
  if (offline_) return;
  f64 lon, lat;
  unproject(proj_, focus.x, focus.y, lon, lat);
  const TileKey c = tile_at(lon, lat);
  // Nearest first: the player's tile, then the ring.
  std::vector<std::pair<i32, TileKey>> want;
  for (i32 dy = converted::neg(ring); dy <= ring; converted::pre_inc(dy))
    for (i32 dx = converted::neg(ring); dx <= ring; converted::pre_inc(dx)) want.push_back({converted::plus(converted::times(dx, dx), converted::times(dy, dy)), TileKey{c.z, converted::plus(c.x, dx), converted::plus(c.y, dy)}});
  std::stable_sort(want.begin(), want.end(), [](const std::pair<i32, TileKey>& a, const std::pair<i32, TileKey>& b) { return a.first < b.first; });
  for (const auto& [d, k] : want) {
    if (tiles_.find(k.hash()) != tiles_.end()) continue;
    auto t = std::make_unique<Tile>();
    converted::present(t)->key = k;
    f64 lo, la, x, y;
    tile_lonlat(k, 0.5, 0.5, lo, la);
    proj_.project(lo, la, x, y);
    converted::present(t)->center = {static_cast<f32>(x), static_cast<f32>(y)};
    f64 x0, y0, x1, y1;
    tile_lonlat(k, 0, 1, lo, la);
    proj_.project(lo, la, x0, y0);
    tile_lonlat(k, 1, 0, lo, la);
    proj_.project(lo, la, x1, y1);
    converted::present(t)->bounds = {static_cast<f32>(x0), static_cast<f32>(y0), static_cast<f32>(x1), static_cast<f32>(y1)};
    tiles_[k.hash()] = std::move(t);
    requests_.push_back(k);
  }
}
Vec4 CityStream::ring_bounds(Vec3 focus, i32 r) const {
  f64 lon, lat, x0, y0, x1, y1;
  unproject(proj_, focus.x, focus.y, lon, lat);
  const TileKey c = tile_at(lon, lat);
  tile_lonlat(TileKey{c.z, converted::minus(c.x, r), converted::plus(c.y, r)}, 0, 1, lon, lat);
  proj_.project(lon, lat, x0, y0);
  tile_lonlat(TileKey{c.z, converted::plus(c.x, r), converted::minus(c.y, r)}, 1, 0, lon, lat);
  proj_.project(lon, lat, x1, y1);
  return {static_cast<f32>(x0), static_cast<f32>(y0), static_cast<f32>(x1), static_cast<f32>(y1)};
}
void CityStream::unload_far(Vec3 focus) {
  f64 lon, lat;
  unproject(proj_, focus.x, focus.y, lon, lat);
  const TileKey c = tile_at(lon, lat);
  std::vector<TileKey> mates;
  for (const Vec3& f : extra_foci) { f64 lo, la; unproject(proj_, f.x, f.y, lo, la); mates.push_back(tile_at(lo, la)); }
  for (auto it = tiles_.begin(); it != tiles_.end();) {
    Tile& t = *converted::present(it->second);
    const i32 d = std::max(std::abs(converted::minus(t.key.x, c.x)), std::abs(converted::minus(t.key.y, c.y)));
    bool near_mate = false;
    for (const TileKey& m : mates) near_mate = near_mate || std::max(std::abs(converted::minus(t.key.x, m.x)), std::abs(converted::minus(t.key.y, m.y))) <= converted::plus(mate_ring, 1);
    if (!t.procedural && d > converted::plus(ring, 1) && !near_mate) {
      remove(t);
      it = tiles_.erase(it);
    } else ++it;
  }
  // Lanes of unloaded tiles stay as dead entries: traffic holds indices into the list.
}
void CityStream::feed_terrain(Tile& t) {
  // world_water.mjs: lakes / harbours (polygons) and waterways (lines with a width per class)
  // become basins in the terrain; bridges keep a solid road over them.
  for (const MapFeatures::Area& a : t.features.areas)
    if (a.kind == AreaKind::water) terrain_.add_water_polygon(a.rings);
    else terrain_.add_tint(t.key.hash(), a.rings, city_stream_cpp_local::area_color(a.kind));  // world_ground.mjs setAreas
  for (const MapFeatures::Road& r : t.features.roads) {
    if (road_is_water(r.cls)) terrain_.add_waterway(r.points, road_width(r.cls), r.cls == RoadClass::river ? 1.6f : r.cls == RoadClass::canal ? 0.5f : 1.1f);
    else if (r.bridge)
      for (std::size_t i = 0; i + 1 < r.points.size(); converted::pre_inc(i)) terrain_.add_bridge(converted::at(r.points, i), converted::at(r.points, i + 1), road_width(r.cls));
  }
}
void CityStream::finish_features(Tile& t) {
  // The streets' corridors first (terrain_craters.mjs setRoadCorridors: every street but paths
  // and tracks, its width + 3.4 m of pavements): the ground of this tile is final with them, and
  // the houses, the streets and everything else are put on it.
  {
    std::vector<f32> widths(converted::count(t.features.roads.size()));
    for (std::size_t i = 0; i < widths.size(); converted::pre_inc(i)) {
      const MapFeatures::Road& r = converted::at(t.features.roads, i);
      if (!road_is_water(r.cls) && r.cls != RoadClass::path && r.cls != RoadClass::track) converted::at(widths, i) = road_width(r.cls) + 3.4f;
    }
    terrain_.set_corridors(t.key.hash(), t.bounds, t.features.roads, widths);
  }
  // Footprint and road streams for the engine's builders, lanes for the traffic.
  t.cent.clear();
  for (MapFeatures::Building& b : t.features.buildings) {
    // terrain_craters.mjs buildingGroundBase: a house stands on the lowest ground of its outline.
    if (!b.rings.empty()) {
      const f32 g = terrain_.footprint_base(converted::at(b.rings, 0));
      b.base += g;
      b.top += g;
    }
    b.full_top = b.top;
    // destruction outlives the tile: a building that was hit stays as it was left
    if (auto d = damage_.find(b.seed); d != damage_.end()) {
      b.top = std::fmin(b.top, b.base + d->second.height);
      b.leveled = d->second.leveled;
    }
    Vec2 c{};
    if (!b.rings.empty() && !converted::at(b.rings, 0).empty()) { for (Vec2 q : converted::at(b.rings, 0)) c = c + q; c = c * (1.0f / static_cast<f32>(converted::at(b.rings, 0).size())); }
    t.cent.push_back(c);
  }
  t.prepared = true;
  ++furniture_serial_;
  for (const MapFeatures::Road& r : t.features.roads) {
    const f32 w = road_width(r.cls);
    const bool water = road_is_water(r.cls);
    if (water) continue;  // drawn by the terrain's water surface
    const bool major = static_cast<u8>(r.cls) <= static_cast<u8>(RoadClass::tertiary);
    const u32 color = water ? city_stream_cpp_local::kWater : r.cls == RoadClass::pedestrian ? city_stream_cpp_local::kPaving
                      : (r.cls == RoadClass::path || r.cls == RoadClass::track) ? city_stream_cpp_local::kPath
                      : major ? city_stream_cpp_local::kAsphaltMajor : city_stream_cpp_local::kAsphalt;
    t.roads.road(r.points.data(), static_cast<u32>(r.points.size()), w, !water && road_drivable(r.cls), color, major && !water ? static_cast<i32>(city_stream_cpp_local::kLine) : -1);
    if (!road_drivable(r.cls)) continue;
    // The lane: the street as far as it lies in this tile's own square. (A vector tile repeats
    // its streets 26 m into the neighbours: there the ground is the neighbour's - final only with
    // its own streets' corridors - and so is the lane. Clipped, the lanes of two tiles meet end to
    // end on the edge: traffic drives on across it, and nobody drives where the ground may yet change.)
    if (t.procedural) { lanes_.push_back(Lane{r.points, w, t.key.hash(), true}); continue; }
    for (std::vector<Vec2>& part : clip_line(r.points, t.bounds)) {
      f32 len = 0;
      for (std::size_t k = 0; k + 1 < part.size(); converted::pre_inc(k)) len += std::hypot(converted::at(part, k + 1).x - converted::at(part, k).x, converted::at(part, k + 1).y - converted::at(part, k).y);
      if (len > 0.5f) lanes_.push_back(Lane{std::move(part), w, t.key.hash(), true});
    }
  }
  // the buildings by cell; the cells round the view are extruded from now on (select_cells), the
  // streets are laid at once
  t.cell_items.clear();
  for (u32 i = 0; i < t.cent.size(); ++i) t.cell_items[city_stream_cpp_local::cell_of(converted::at(t.cent, i))].push_back(i);
  select_cells(focus_, true);
  begin_roads(t);
}
void CityStream::select_cells(Vec3 focus, bool force) {
  // The drawn city (world_city_buildings.mjs: the nearest MAX_FOOTPRINTS buildings within
  // VISUAL_RADIUS_M 900 m), by cell: the cells within the radius of the way ahead - from the
  // player to where he will be in a few seconds (`view_lead`) - nearest first, up to the budget of
  // buildings. A cell that is wanted is built once and kept; it goes when it lies well outside
  // the radius. So driving on only adds the cells that come into view ahead - the houses already
  // standing are never built again, and nothing is missing where the player arrives.
  const f64 now = ::converted_SpawnCity__spiel_cpp::now_ms();
  const Vec2 ahead{focus.x + view_lead.x, focus.y + view_lead.y};
  if (!force && std::hypot(focus.x - vis_at_.x, focus.y - vis_at_.y) < 40 && std::hypot(ahead.x - vis_ahead_.x, ahead.y - vis_ahead_.y) < 60 && now - vis_ms_ < 1000) return;
  vis_at_ = {focus.x, focus.y};
  vis_ahead_ = ahead;
  vis_ms_ = now;
  constexpr f32 kR = 900, kKeep = 220;
  const Vec2 a{focus.x, focus.y}, ab = ahead - a;
  const f32 ab2 = ab.x * ab.x + ab.y * ab.y;
  auto way_distance = [&](Vec2 p) {
    const f32 t = ab2 > 1 ? clampf(((p.x - a.x) * ab.x + (p.y - a.y) * ab.y) / ab2, 0, 1) : 0;
    return std::hypot(p.x - a.x - ab.x * t, p.y - a.y - ab.y * t);
  };
  struct Pick { f32 d; u32 tile; u64 cell; u32 n; };  // (tile: its place among tiles_)
  std::vector<Pick> picks;
  for (auto it = tiles_.begin(); it != tiles_.end(); ++it) {
    const Tile& t = *converted::present(it->second);
    if (!t.prepared) continue;
    for (const auto& [cell, items] : t.cell_items) {
      const i32 cx = static_cast<i32>(static_cast<u32>(cell >> 32)), cy = static_cast<i32>(static_cast<u32>(cell));
      const f32 d = way_distance({(static_cast<f32>(cx) + 0.5f) * city_stream_cpp_local::kChunk, (static_cast<f32>(cy) + 0.5f) * city_stream_cpp_local::kChunk});
      if (d <= kR + kKeep) picks.push_back({d, static_cast<u32>(it - tiles_.begin()), cell, static_cast<u32>(items.size())});
    }
  }
  std::stable_sort(picks.begin(), picks.end(), [](const Pick& x, const Pick& y) { return x.d < y.d || (x.d == y.d && x.cell < y.cell); });
  for (auto& [k, tp] : tiles_) converted::present(tp)->want_cells.clear();
  u32 total = 0;
  f32 reach = kR;
  for (const Pick& p : picks) {
    if (p.d > kR) break;
    if (total >= building_budget && p.d > 240) { reach = p.d; break; }  // (what is next to the player is always drawn)
    converted::present((tiles_.begin() + p.tile)->second)->want_cells.insert(p.cell);
    total += p.n;
  }
  auto settle = [&](Tile& t, const Pick& p) {
    const bool want = t.want_cells.count(p.cell) != 0, built = t.cell_ids.count(p.cell) != 0;
    if (want && !built) t.dirty_cells.insert(p.cell);
    if (!want && !built) t.dirty_cells.erase(p.cell);
    // a built cell stays while it is near the drawn radius (no flicker at its edge)
    if (!want && built && p.d > reach + kKeep * 0.5f && !t.cell_job && !t.cell_uploading) drop_cell(t, p.cell);
  };
  for (const Pick& p : picks) settle(*converted::present((tiles_.begin() + p.tile)->second), p);
  // cells beyond every radius (the player was put somewhere else): gone
  for (auto& [k, tp] : tiles_) {
    Tile& t = *converted::present(tp);
    if (t.cell_job || t.cell_uploading) continue;
    std::vector<u64> far;
    for (const auto& [cell, ids] : t.cell_ids) {
      if (t.want_cells.count(cell)) continue;
      const i32 cx = static_cast<i32>(static_cast<u32>(cell >> 32)), cy = static_cast<i32>(static_cast<u32>(cell));
      if (way_distance({(static_cast<f32>(cx) + 0.5f) * city_stream_cpp_local::kChunk, (static_cast<f32>(cy) + 0.5f) * city_stream_cpp_local::kChunk}) > kR + kKeep) far.push_back(cell);
    }
    for (u64 c : far) drop_cell(t, c);
  }
}
void CityStream::drop_cell(Tile& t, u64 cell) {
  auto it = t.cell_ids.find(cell);
  if (it == t.cell_ids.end()) return;
  for (u32 id : it->second) {
    r_->remove(id);
    converted::erase(t.meshes, std::remove(t.meshes.begin(), t.meshes.end(), id), t.meshes.end());
  }
  t.cell_ids.erase(it);
  t.dirty_cells.erase(cell);
}
void CityStream::upload(Tile& t, GeoChunk& chunk, const Material& material, bool walls) {
  if (chunk.mesh.vertex_count() == 0) return;
  if (!chunk.welded) ::converted_SpawnCity__spiel_cpp::weld(chunk.mesh);
  const u32 id = r_->allocate_id();
  ++upload_count_;
  upload_vertices_ += chunk.mesh.vertex_count();
  MeshLook look;
  look.material = material;
  look.extra_slot = walls ? 0 : kMaxExtensionAttributes;
  look.pick_bvh = false;  // hits are Box3D rays (the collision set); no picking BVH to build per chunk
  if (!::converted_SpawnCity__spiel_cpp::upsert(*r_, id, chunk.mesh, look)) { r_->release_id(id); return; }
  t.meshes.push_back(id);
  if (walls) t.cell_ids[city_stream_cpp_local::cell_key(chunk.x, chunk.y)].push_back(id);
  t.triangles += chunk.mesh.triangle_count();
}
void CityStream::begin_roads(Tile& t) {
  RoadOptions ro;
  // world_city_roads.mjs RADIUS_M 720 around the player - and along his way ahead (view_lead)
  const Vec2 mid{focus_.x + view_lead.x * 0.5f, focus_.y + view_lead.y * 0.5f};
  ro.center_x = mid.x;
  ro.center_y = mid.y;
  ro.radius = 720 + std::hypot(view_lead.x, view_lead.y) * 0.5f;
  ro.segment_length = 4;  // follows the 5 m terrain nodes
  ro.palette = city_stream_cpp_local::road_palette();
  // over a crater the ribbon is draped finely (0.9 m quads): it lies in the bowl, not over it
  ro.deformed = [this](f64 x, f64 y, f64 r) { return terrain_.deformed(static_cast<f32>(x), static_cast<f32>(y), static_cast<f32>(r)); };
  t.road_builder.begin(t.roads.data(), t.roads.size(), ro, terrain_.sampler());
  t.roads_at = mid;
  ++relays_;
  t.upload_next = 0;
  t.state = Tile::State::roads;
}
void CityStream::relay(const Vec4& rect) {
  for (auto& [k, tp] : tiles_) {
    Tile& t = *converted::present(tp);
    if (rect.x > t.bounds.z || rect.z < t.bounds.x || rect.y > t.bounds.w || rect.w < t.bounds.y) continue;
    // a new crater while this tile's roads are being re-laid: once more after that (the layer
    // being built sampled the ground before it)
    if (t.relay || t.state != Tile::State::ready) { if (t.relay) t.relay_again = true; continue; }
    t.relay = true;
    t.old_lay = std::move(t.lay_meshes);
    t.lay_meshes.clear();
    begin_roads(t);
  }
}
void CityStream::begin_cells(Tile& t) {
  // the cells to build (wanted and not there yet, or damaged), the nearest first - a few per job,
  // so the first ones stand soon and no upload step is long
  std::vector<std::pair<f32, u64>> order;
  for (u64 c : t.dirty_cells) {
    const i32 cx = static_cast<i32>(static_cast<u32>(c >> 32)), cy = static_cast<i32>(static_cast<u32>(c));
    order.push_back({std::hypot((static_cast<f32>(cx) + 0.5f) * city_stream_cpp_local::kChunk - focus_.x, (static_cast<f32>(cy) + 0.5f) * city_stream_cpp_local::kChunk - focus_.y), c});
  }
  std::stable_sort(order.begin(), order.end(), [](const std::pair<f32, u64>& a, const std::pair<f32, u64>& b) { return a.first < b.first || (!(b.first < a.first) && a.second < b.second); });
  if (order.size() > 6) order.resize(converted::count(6));
  FootprintStream fs;
  std::vector<Vec2> thin;
  t.job_cells.clear();
  for (const auto& [d, c] : order) {
    t.job_cells.push_back(c);
    t.dirty_cells.erase(c);
    const auto it = t.cell_items.find(c);
    if (it == t.cell_items.end()) continue;
    for (u32 i : it->second) city_stream_cpp_local::put_footprint(fs, converted::at(t.features.buildings, i), converted::at(t.cent, i), thin);
  }
  t.cell_job = jobs::submit(cityjobs::kBuildings, cityjobs::buildings_input(fs, city_stream_cpp_local::building_options()));
}
bool CityStream::finish_cells(Tile& t, f64 deadline) {
  if (!t.cell_uploading) {
    if (!jobs::take(t.cell_job, t.built_bytes)) return false;
    t.cell_job = 0;
    // what the job replaces is kept until its meshes are all there: nothing pops out
    for (u64 c : t.job_cells) {
      auto it = t.cell_ids.find(c);
      if (it != t.cell_ids.end()) { t.cell_old[c] = std::move(it->second); t.cell_ids.erase(it); }
    }
    t.built_at = 4;
    t.upload_next = cityjobs::chunk_count(t.built_bytes);
    t.cell_uploading = true;
  }
  // one finished chunk mesh at a time, read straight from the job's output: no step longer than
  // one chunk
  Material m;
  m.roughness = 0.82f;
  while (t.upload_next > 0) {
    GeoChunk chunk;
    if (!cityjobs::read_chunk(t.built_bytes, t.built_at, chunk)) { t.upload_next = 0; break; }
    converted::pre_dec(t.upload_next);
    const f64 t1 = ::converted_SpawnCity__spiel_cpp::now_ms();
    upload(t, chunk, m, true);
    step_time("building.upload", t1);
    if (t.upload_next > 0 && ::converted_SpawnCity__spiel_cpp::now_ms() > deadline) return false;
  }
  t.built_bytes.clear();
  t.built_bytes.shrink_to_fit();
  for (auto& [c, ids] : t.cell_old)
    for (u32 id : ids) {
      r_->remove(id);
      converted::erase(t.meshes, std::remove(t.meshes.begin(), t.meshes.end(), id), t.meshes.end());
    }
  t.cell_old.clear();
  for (u64 c : t.job_cells) {
    t.cell_ids[c];  // built (a cell without a mesh too)
    // not wanted any more by now (the player went on): it goes with the next selection
  }
  t.job_cells.clear();
  t.cell_uploading = false;
  ++rebuilds_;
  if (ms_.t_built < 0 && t.key == origin_tile_) ms_.t_built = ::converted_SpawnCity__spiel_cpp::now_ms() - start_ms_;
  return true;
}
bool CityStream::work(Tile& t, f64 deadline) {
  using S = Tile::State;
  switch (t.state) {
    case S::ready:
      // the drawn cells: built off the frame, uploaded a chunk a step, swapped when complete
      if (t.cell_job || t.cell_uploading) {
        const f64 t1 = ::converted_SpawnCity__spiel_cpp::now_ms();
        const bool done = finish_cells(t, deadline);
        step_time("cells.swap", t1);
        if (!done) return ::converted_SpawnCity__spiel_cpp::now_ms() <= deadline;
      }
      if (!t.dirty_cells.empty() && !t.cell_job && !t.cell_uploading) {
        const f64 t1 = ::converted_SpawnCity__spiel_cpp::now_ms();
        begin_cells(t);
        step_time("cells.begin", t1);
      }
      // the streets round the player (world_city_roads.mjs RADIUS_M 720): laid again after
      // REBUILD_MOVE_M 260 m of travel
      if (const Vec2 mid{focus_.x + view_lead.x * 0.5f, focus_.y + view_lead.y * 0.5f};
          !t.relay && std::hypot(mid.x - t.roads_at.x, mid.y - t.roads_at.y) >= 260 && city_stream_cpp_local::rect_distance_to(t.bounds, mid.x, mid.y) < converted::plus(720, 260) + std::hypot(view_lead.x, view_lead.y) * 0.5f) {
        t.relay = true;
        t.old_lay = std::move(t.lay_meshes);
        t.lay_meshes.clear();
        begin_roads(t);
        return ::converted_SpawnCity__spiel_cpp::now_ms() <= deadline;
      }
      return ::converted_SpawnCity__spiel_cpp::now_ms() <= deadline;
    case S::requested:
    case S::failed: return true;
    case S::decoding: {
      std::vector<u8> out;
      if (!jobs::take(t.tile_job, out)) return true;  // still decoding off the frame: next tile
      t.tile_job = 0;
      if (!cityjobs::read_features(out, t.features)) { t.state = S::failed; return true; }
      ++real_tiles_;
      if (t.key == origin_tile_ && ms_.t_decoded < 0) ms_.t_decoded = ::converted_SpawnCity__spiel_cpp::now_ms() - start_ms_;
      feed_terrain(t);
      t.state = S::terrain_wait;
      return ::converted_SpawnCity__spiel_cpp::now_ms() > deadline ? false : work(t, deadline);
    }
    case S::terrain_wait:
      // Buildings and streets stand on the terrain: wait until the ground of the whole tile is
      // known for good (terrain.h covers) - a house is never based on a height that changes later.
      // (the tile's data reaches a little over its square - its buffer - and the streets' profile
      // is smoothed over the ground beside them: 80 m more must be known)
      if (!terrain_.settled() || !terrain_.covers({t.bounds.x - 80, t.bounds.y - 80, t.bounds.z + 80, t.bounds.w + 80})) return true;
      if (ms_.t_terrain < 0) ms_.t_terrain = ::converted_SpawnCity__spiel_cpp::now_ms() - start_ms_;
      finish_features(t);
      return ::converted_SpawnCity__spiel_cpp::now_ms() > deadline ? false : work(t, deadline);
    case S::building:
      // (the drawn buildings are cells now - see S::ready; a tile goes from its features to its streets)
      begin_roads(t);
      return ::converted_SpawnCity__spiel_cpp::now_ms() > deadline ? false : work(t, deadline);
    case S::roads: {
      {
        const f64 t1 = ::converted_SpawnCity__spiel_cpp::now_ms();
        const bool built = t.road_builder.step(std::max(0.5, deadline - ::converted_SpawnCity__spiel_cpp::now_ms()));
        step_time("roads.build", t1);
        if (!built) return false;
      }
      Material m;
      m.roughness = 0.95f;
      m.cast_shadow = false;
      m.double_sided = true;
      auto& chunks = t.road_builder.chunks();
      while (t.upload_next < chunks.size()) {
        const std::size_t before = t.meshes.size();
        const f64 t1 = ::converted_SpawnCity__spiel_cpp::now_ms();
        GeoChunk chunk = std::move(converted::at(chunks, t.upload_next));   // (out of the engine's list: upload welds it)
        upload(t, chunk, m, false);
        step_time("roads.upload", t1);
        // road meshes are the re-layable ones
        t.lay_meshes.insert(t.lay_meshes.end(), t.meshes.begin() + static_cast<std::ptrdiff_t>(before), t.meshes.end());
        t.meshes.resize(converted::count(before));
        converted::at(chunks, converted::post_inc(t.upload_next)).mesh = MeshData{};
        if (::converted_SpawnCity__spiel_cpp::now_ms() > deadline) return false;
      }
      chunks.clear();
      chunks.shrink_to_fit();
      t.upload_next = 0;
      t.state = S::areas;
      return ::converted_SpawnCity__spiel_cpp::now_ms() > deadline ? false : work(t, deadline);
    }
    case S::areas:
      // the map areas are painted into the ground (Terrain::add_tint), as in world_ground.mjs
      if (t.relay) {
        // New layer in place: the old one goes now (no frame without roads).
        for (u32 id : t.old_lay) r_->remove(id);
        t.old_lay.clear();
        t.relay = false;
        t.state = S::ready;
        if (t.relay_again) {
          t.relay_again = false;
          t.relay = true;
          t.old_lay = std::move(t.lay_meshes);
          t.lay_meshes.clear();
          begin_roads(t);
        }
        return true;
      }
      t.state = S::ready;  // collision: the working set around the player (update_collision)
      // a new set only when this tile brings buildings into the 340 m around the player
      for (Vec2 c : t.cent)
        if (std::hypot(c.x - focus_.x, c.y - focus_.y) <= 340) { near_.dirty = true; break; }
      return true;
    case S::collision:
      t.state = S::ready;
      return true;
  }
  return true;
}
void CityStream::update(Vec3 focus, f64 budget_ms) {
  if (!r_ || !world_) return;
  const f64 start = ::converted_SpawnCity__spiel_cpp::now_ms(), deadline = start + budget_ms;
  // without workers / threads the jobs run here, inside the frame's budget
  f64 t0 = ::converted_SpawnCity__spiel_cpp::now_ms();
  jobs::pump(budget_ms * 0.5);
  step_time("jobs", t0);
  focus_ = focus;
  t0 = ::converted_SpawnCity__spiel_cpp::now_ms();
  select_cells(focus, false);
  step_time("select_cells", t0);
  t0 = ::converted_SpawnCity__spiel_cpp::now_ms();
  request_around(focus, ring);
  for (const Vec3& f : extra_foci) request_around(f, mate_ring);  // MP host: the town around the mates too
  for (auto& [k, tp] : tiles_)
    if (converted::present(tp)->state == Tile::State::failed && start >= converted::present(tp)->retry_ms) { converted::present(tp)->state = Tile::State::requested; requests_.push_back(converted::present(tp)->key); }
  unload_far(focus);
  step_time("request/unload", t0);
  t0 = ::converted_SpawnCity__spiel_cpp::now_ms();
  terrain_.extra = extra_foci;
  // the ground the city needs: the squares of the tiles round the player and round each mate
  terrain_.needs.clear();
  if (!offline_) {
    auto grown = [](Vec4 r) { return Vec4{r.x - 80, r.y - 80, r.z + 80, r.w + 80}; };
    terrain_.needs.push_back(grown(ring_bounds(focus, ring)));
    for (const Vec3& f : extra_foci) terrain_.needs.push_back(grown(ring_bounds(f, mate_ring)));
  }
  terrain_.update(focus, anchor, std::fmax(1.0, budget_ms * 0.45));
  step_time("terrain", t0);
  t0 = ::converted_SpawnCity__spiel_cpp::now_ms();
  terrain_.take_changes(terrain_changes_);
  for (const Vec4& r : terrain_changes_) { relay(r); ground_changes_.push_back(r); }
  terrain_changes_.clear();
  step_time("relay", t0);
  // (the collision round the player: collide, in the game's fixed step)
  // Nearest unfinished tile first: each tile by its key, with its distance (squared) - stably, so tiles as far
  // keep the order of the map.
  std::vector<std::pair<f32, u64>> order;
  for (auto& [k, t] : tiles_) order.push_back({(converted::present(t)->center.x - focus.x) * (converted::present(t)->center.x - focus.x) + (converted::present(t)->center.y - focus.y) * (converted::present(t)->center.y - focus.y), k});
  std::stable_sort(order.begin(), order.end(), [](const std::pair<f32, u64>& a, const std::pair<f32, u64>& b) { return a.first < b.first; });
  static const char* kStateName[] = {"requested", "decoding", "terrain_wait", "building", "roads", "areas", "collision", "ready", "failed"};
  for (const auto& [d, k] : order) {
    if (::converted_SpawnCity__spiel_cpp::now_ms() > deadline) break;
    t0 = ::converted_SpawnCity__spiel_cpp::now_ms();
    auto it = tiles_.find(k);
    Tile& t = *converted::present(it->second);
    const char* name = converted::at(kStateName, static_cast<u32>(t.state));
    const bool more = work(t, deadline);
    step_time(name, t0);
    if (!more) break;
  }
  stats_ = {};
  for (auto& [k, t] : tiles_) {
    if (converted::present(t)->state == Tile::State::ready) ++stats_.tiles_ready;
    else if (converted::present(t)->state == Tile::State::failed) ++stats_.tiles_failed;
    else ++stats_.tiles_loading;
    stats_.buildings += static_cast<u32>(converted::present(t)->features.buildings.size());

    stats_.triangles += converted::present(t)->triangles;
    stats_.meshes += static_cast<u32>(converted::present(t)->meshes.size() + converted::present(t)->lay_meshes.size());
  }
  stats_.colliders = near_.colliders;
  ms_.work_ms += ::converted_SpawnCity__spiel_cpp::now_ms() - start;
  stats_.t_request = ms_.t_request; stats_.t_data = ms_.t_data; stats_.t_decoded = ms_.t_decoded; stats_.t_terrain = ms_.t_terrain;
  stats_.t_built = ms_.t_built; stats_.t_collision = ms_.t_collision; stats_.work_ms = ms_.work_ms;
  stats_.rebuilds = rebuilds_;
  stats_.uploads = upload_count_;
  stats_.upload_vertices = static_cast<u32>(upload_vertices_ / 1000);
  stats_.relays = relays_;
  stats_.last_slice_ms = ::converted_SpawnCity__spiel_cpp::now_ms() - start;
  if (::converted_SpawnCity__spiel_cpp::now_ms() - worst_at_ > 2000) { worst_ = 0; worst_at_ = ::converted_SpawnCity__spiel_cpp::now_ms(); worst_step_ = ""; worst_step_ms_ = 0; }
  worst_ = std::fmax(worst_, stats_.last_slice_ms);
  stats_.worst_ms = worst_;
  stats_.worst_step = worst_step_;
  stats_.worst_step_ms = worst_step_ms_;
}
void CityStream::step_time(const char* name, f64 t0) {
  const f64 took = ::converted_SpawnCity__spiel_cpp::now_ms() - t0;
  if (took > worst_step_ms_) { worst_step_ms_ = took; worst_step_ = name; }
}
bool Terrain::corridors_at(f32 x, f32 y) const { return !corridors_expected || corridor_set(x, y) >= 0; }
bool CityStream::loaded_at(Vec3 p) const {
  if (!terrain_.settled()) return false;
  if (offline_) {
    for (const auto& [k, t] : tiles_)
      if (converted::present(t)->procedural) return converted::present(t)->state == Tile::State::ready;
    return false;
  }
  // As the original: the game starts as soon as the ground under the player is there - its
  // elevation and the streets that level it (terrain.h set_corridors); the city (drawn set,
  // collision set) streams in around him (world_spawn_guard: see Game::spawn_guard).
  return terrain_.corridors_at(p.x, p.y);
}
namespace drone_art_cpp_local { Mat4 rot(Vec3 axis, f32 a) { return Mat4::trs({}, Quat::axis_angle(axis, a), {1, 1, 1}); } }
namespace drone_art_cpp_local { Mat4 at(Vec3 p) { return Mat4::translate(p); } }
void DroneArt::clear(Part& p) {
  p.transforms.clear();
  p.tints.clear();
}
void DroneArt::put(Part& p, const Mat4& m, Vec3 tint) {
  p.transforms.insert(p.transforms.end(), m.m, m.m + 16);
  if (p.tinted) p.tints.insert(p.tints.end(), {tint.x, tint.y, tint.z, 1});
}
void DroneArt::upload(Part& p) {
  if (!p.id) return;
  if (p.transforms.empty()) { r_->set_visible(p.id, false); return; }
  r_->update_instances(p.id, Span<const f32>(p.transforms), Span<const f32>(p.tints));
  r_->set_visible(p.id, true);
}
void DroneArt::draw(const Mat4& body, const std::array<Vec3, 4>& motors, const std::array<f32, 4>& rotor_angles, f32 prop_d, bool armed, bool fpv_view) {
  clear(frame_);
  clear(motor_);
  clear(prop_a_);
  clear(prop_b_);
  clear(led_);
  if (!fpv_view) {
    put(frame_, body);
    for (int i = 0; i < 4; converted::pre_inc(i)) {
      put(motor_, body * drone_art_cpp_local::at(converted::at(motors, i) + Vec3{0, 0, -0.004f}));
      const Mat4 p = body * drone_art_cpp_local::at(converted::at(motors, i) + Vec3{0, 0, 0.018f}) * drone_art_cpp_local::rot({0, 0, 1}, converted::at(rotor_angles, i)) * Mat4::scale({prop_d, 1, 1});
      if (i % 2) put(prop_b_, p);
      else put(prop_a_, p);
    }
    put(led_, body * drone_art_cpp_local::at({0.06f, 0, 0.018f}), armed ? Vec3{4, 0.2f, 0.1f} : Vec3{0.3f, 0.3f, 0.3f});
  }
  upload(frame_);
  upload(motor_);
  upload(prop_a_);
  upload(prop_b_);
  upload(led_);
}
void DroneArt::hide() {
  clear(frame_);
  clear(motor_);
  clear(prop_a_);
  clear(prop_b_);
  clear(led_);
  upload(frame_);
  upload(motor_);
  upload(prop_a_);
  upload(prop_b_);
  upload(led_);
}
void SoundFx::drive(Loop& l, bool on, Vec3 pos, Vec3 vel, f32 volume, f32 pitch, bool spatial, f32 max_distance) {
  if (!mixer_ || !l.clip) return;
  if (!on || volume < 0.002f) {
    if (l.voice) { mixer_->stop(l.voice, 0.15f); l.voice = 0; }
    return;
  }
  if (!l.voice || !mixer_->playing(l.voice)) {
    audio::PlayParams p;
    p.loop = true;
    p.volume = volume;
    p.pitch = pitch;
    p.spatial = spatial;
    p.position = pos;
    p.velocity = vel;
    p.min_distance = 3;
    p.max_distance = max_distance;
    p.bus = audio::Bus::sfx;
    p.fade_in = 0.1f;
    l.voice = mixer_->play(l.clip, p);
    return;
  }
  mixer_->set_volume(l.voice, volume);
  mixer_->set_pitch(l.voice, clampf(pitch, 0.05f, 8));
  if (spatial) mixer_->set_position(l.voice, pos, vel);
}
void SoundFx::update(const SoundState& s, f32 dt) {
  (void)dt;
  // Drone: SpawnCity mixes it at 50 % (audio_settings.mjs drone 50).
  drive(rotor_, s.drone.active, s.drone.position, s.drone.velocity, s.drone_mix * 0.5f * clampf(0.15f + s.drone.rate, 0, 1), 0.35f + 1.9f * s.drone.rate, true, 140);
  drive(prop_wash_, s.drone.active, s.drone.position, s.drone.velocity, s.drone_mix * 0.35f * s.drone.load, 0.7f + 0.6f * s.drone.rate, true, 90);
  // Vehicle 58 %.
  drive(engine_, s.car.active, s.car.position, s.car.velocity, s.vehicle_mix * 0.58f * (0.35f + 0.65f * s.car.load), 0.75f + 2.2f * s.car.rate, true, 120);
  drive(turbine_, s.jet.active, s.jet.position, s.jet.velocity, s.vehicle_mix * 0.45f * clampf(0.2f + s.jet.rate, 0, 1), 0.55f + 0.8f * s.jet.rate, true, 900);
  drive(roar_, s.jet.active, s.jet.position, s.jet.velocity, s.vehicle_mix * 0.9f * s.jet.load, 0.7f + 0.5f * s.jet.load, true, 1500);
  drive(siren_, s.siren.active, s.siren.position, s.siren.velocity, 0.42f, 1.0f, true, 260);
  drive(wind_, true, {}, {}, clampf((s.wind - 6) / 60, 0, 0.7f), 0.8f + std::fmin(0.6f, s.wind / 120), false, 0);
}
void Terrain::build_collision_tile(i32 ti, i32 tj) {
  // terrain_tiles.mjs: 32 cells of 5 m plus one cell into each neighbour with the outer ring sunk,
  // so the seam is an interior edge of both tiles (no ghost contacts on fast wheels).
  const i32 N = converted::plus(terrain_cpp_local::kCells, 3);
  const f32 x0 = ti * terrain_cpp_local::kTile - kStep, y0 = tj * terrain_cpp_local::kTile - kStep;
  std::vector<Vec3> pts(converted::count(static_cast<std::size_t>(N) * N));
  for (i32 r = 0; r < N; converted::pre_inc(r))
    for (i32 c = 0; c < N; converted::pre_inc(c)) {
      const f32 x = x0 + c * kStep, y = y0 + r * kStep;
      f32 z = node_height(x, y);
      if (r == 0 || c == 0 || r == converted::minus(N, 1) || c == converted::minus(N, 1)) z -= kSkirtDrop;
      converted::at(pts, static_cast<std::size_t>(r) * N + c) = {x, y, z};
    }
  std::vector<u32> idx;
  idx.reserve(converted::count(static_cast<std::size_t>(converted::minus(N, 1)) * (converted::minus(N, 1)) * 6));
  for (i32 r = 0; converted::plus(r, 1) < N; converted::pre_inc(r))
    for (i32 c = 0; converted::plus(c, 1) < N; converted::pre_inc(c)) {
      const u32 a = static_cast<u32>(converted::plus(converted::times(r, N), c)), b = a + 1, cc = a + static_cast<u32>(N), d = cc + 1;
      idx.insert(idx.end(), {a, b, d, a, d, cc});
    }
  // the same ground as the tile already has (a street laid again, a change beside it): nothing is written - the
  // physics world sees a change of the ground only when there is one
  CollisionTile& t = collision_[terrain_cpp_local::key2(ti, tj)];
  if (t.body.valid() && world_->body_valid(t.body) && t.pts.size() == pts.size()) {
    bool same = true;
    for (std::size_t q = 0; q < pts.size() && same; converted::pre_inc(q)) same = converted::at(t.pts, q).x == converted::at(pts, q).x && converted::at(t.pts, q).y == converted::at(pts, q).y && converted::at(t.pts, q).z == converted::at(pts, q).z;
    if (same) return;
  }
  physics::BodySettings bs;
  bs.type = physics::BodyType::fixed;
  const physics::Body body = world_->create_body(bs);
  physics::ShapeSettings ss;
  ss.kind = physics::ShapeKind::mesh;
  ss.points = Span<const Vec3>(pts.data(), pts.size());
  ss.indices = Span<const u32>(idx.data(), idx.size());
  ss.material.friction = 0.8f;  // the level's ground friction so far
  ss.material.category_bits = kCatWorld;
  world_->create_shape(body, ss);
  // New field first, then the old one goes (terrain_tiles.mjs writeTile order).
  if (t.body.valid() && world_->body_valid(t.body)) world_->destroy_body(t.body);
  t.body = body;
  t.pts = std::move(pts);
}
void Terrain::collide(Vec3 focus, Vec3 anchor, u32 more) {
  if (!world_ || !settled_) return;
  bool extra_moved = extra.size() != planned_extra_.size();
  for (std::size_t i = 0; !extra_moved && i < extra.size(); converted::pre_inc(i)) extra_moved = std::hypot(converted::at(extra, i).x - converted::at(planned_extra_, i).x, converted::at(extra, i).y - converted::at(planned_extra_, i).y) > 40;
  if (replan_ || extra_moved || std::hypot(focus.x - planned_focus_.x, focus.y - planned_focus_.y) > 40 ||
      std::hypot(anchor.x - planned_anchor_.x, anchor.y - planned_anchor_.y) > 40)
    want_tiles(focus, anchor);
  // the ground right under the focus and the anchor (and their neighbours) before the step, whatever it costs: a
  // jet at 250 m/s or a reload of the elevation never leaves a hole under anybody
  std::vector<Vec3> under{focus, anchor};
  under.insert(under.end(), extra.begin(), extra.end());
  for (const Vec3& at : under) {
    const i32 ci = static_cast<i32>(converted::fits<int>(std::floor(at.x / terrain_cpp_local::kTile))), cj = static_cast<i32>(converted::fits<int>(std::floor(at.y / terrain_cpp_local::kTile)));
    for (i32 j = converted::minus(cj, 1); j <= converted::plus(cj, 1); converted::pre_inc(j))
      for (i32 i = converted::minus(ci, 1); i <= converted::plus(ci, 1); converted::pre_inc(i)) {
        const u64 k = terrain_cpp_local::key2(i, j);
        if (collision_.count(k) && !dirty_collision_.count(k)) continue;
        build_collision_tile(i, j);
        dirty_collision_.erase(k);
        ++stats_.rebuilds;
      }
  }
  // the other wanted tiles (what stands on them must not fall): `more` in this step, the nearest first
  bool missing = false;
  u32 built = 0;
  for (u64 k : want_collision_) {
    if (collision_.count(k) && !dirty_collision_.count(k)) continue;
    if (built >= more) { missing = true; break; }
    build_collision_tile(static_cast<i32>(k >> 32), static_cast<i32>(k & 0xffffffffu));
    dirty_collision_.erase(k);
    ++stats_.rebuilds;
    ++built;
  }
  if (!missing && collision_.size() > want_collision_.size()) {
    // every wanted tile stands: what is no longer wanted goes (never before - no holes)
    const kern::Set<u64> keep(want_collision_.begin(), want_collision_.end());
    for (auto it = collision_.begin(); it != collision_.end();) {
      if (!keep.count(it->first)) {
        if (it->second.body.valid() && world_->body_valid(it->second.body)) world_->destroy_body(it->second.body);
        dirty_collision_.erase(it->first);
        it = collision_.erase(it);
      } else ++it;
    }
  }
  stats_.collision_tiles = static_cast<u32>(collision_.size());
}
namespace city_stream_cpp_local { f64 signed_area(const std::vector<Vec2>& r) {
  f64 a = 0;
  for (std::size_t i = 0, j = r.size() - 1; i < r.size(); j = converted::post_inc(i)) a += static_cast<f64>(converted::at(r, j).x) * converted::at(r, i).y - static_cast<f64>(converted::at(r, i).x) * converted::at(r, j).y;
  return a * 0.5;
} }
void CityStream::collide(Vec3 focus, bool whole) {
  if (!world_) return;
  terrain_.collide(focus, anchor, whole ? 1000000u : 1u);
  if (near_.steps < kNearSteps) ++near_.steps;
  update_collision(focus, whole);
  stats_.colliders = near_.colliders;
  stats_.t_collision = ms_.t_collision;
}
void CityStream::update_collision(Vec3 focus, bool whole) {
  NearCollision& n = near_;
  // (along the way ahead - view_lead: a fast car has its walls before it gets there)
  const Vec2 way_a{focus.x, focus.y}, way_ab{view_lead.x, view_lead.y};
  const f32 way_l2 = way_ab.x * way_ab.x + way_ab.y * way_ab.y;
  auto way_d2 = [&](Vec2 p) {
    const f32 t = way_l2 > 1 ? clampf(((p.x - way_a.x) * way_ab.x + (p.y - way_a.y) * way_ab.y) / way_l2, 0, 1) : 0;
    const f32 dx = p.x - way_a.x - way_ab.x * t, dy = p.y - way_a.y - way_ab.y * t;
    return dx * dx + dy * dy;
  };
  bool moved = std::hypot(focus.x - n.at.x, focus.y - n.at.y) >= 140 || std::hypot(focus.x + view_lead.x - n.ahead.x, focus.y + view_lead.y - n.ahead.y) >= 140 ||
               extra_foci.size() != n.mates_at.size();
  for (std::size_t i = 0; !moved && i < extra_foci.size(); converted::pre_inc(i)) moved = std::hypot(converted::at(extra_foci, i).x - converted::at(n.mates_at, i).x, converted::at(extra_foci, i).y - converted::at(n.mates_at, i).y) >= 140;
  if (!n.building && (moved || (n.dirty && n.steps >= kNearSteps))) {
    // world_building_collisions.mjs: the nearest MAX_FOOTPRINTS 480 within RADIUS_M 340
    struct Pick { f32 d2; u64 tile; u32 i; };
    std::vector<Pick> all;
    for (auto& [k, tp] : tiles_) {
      const Tile& t = *converted::present(tp);
      if (t.state != Tile::State::ready && t.state != Tile::State::building && t.state != Tile::State::roads && t.state != Tile::State::areas) continue;
      if (!t.prepared) continue;
      for (u32 i = 0; i < t.cent.size(); ++i) {
        if (k == excl_tile_ && static_cast<i32>(i) == excl_index_) continue;  // an entered interior (M3 life)
        f32 d2 = way_d2(converted::at(t.cent, i));
        // (MP host: the buildings around the mates too - his traffic and people there collide)
        for (const Vec3& m : extra_foci) { const f32 mx = converted::at(t.cent, i).x - m.x, my = converted::at(t.cent, i).y - m.y; d2 = std::fmin(d2, mx * mx + my * my); }
        if (d2 <= 340.0f * 340.0f) all.push_back({d2, k, i});
      }
    }
    std::stable_sort(all.begin(), all.end(), [](const Pick& a, const Pick& b) { return a.d2 < b.d2; });
    const std::size_t cap = 480 + 320 * extra_foci.size();
    if (all.size() > cap) all.resize(converted::count(cap));
    n.list.clear();
    for (const Pick& p : all) n.list.push_back({p.tile, p.i});
    n.old_body = n.body;
    n.body = {};
    n.next = 0;
    n.colliders = 0;
    n.building = true;
    n.dirty = false;
    n.at = {focus.x, focus.y};
    n.ahead = {focus.x + view_lead.x, focus.y + view_lead.y};
    n.mates_at = extra_foci;
    n.steps = 0;
  }
  if (n.building && build_near(whole)) {
    if (n.old_body.valid() && world_->body_valid(n.old_body)) world_->destroy_body(n.old_body);
    n.old_body = {};
    n.building = false;
    n.built = true;
    if (ms_.t_collision < 0 && !n.list.empty()) ms_.t_collision = ::converted_SpawnCity__spiel_cpp::now_ms() - start_ms_;
  }
}
bool CityStream::build_near(bool whole) {
  NearCollision& n = near_;
  u32 built = 0;
  if (!n.body.valid()) {
    physics::BodySettings bs;
    bs.type = physics::BodyType::fixed;
    n.body = world_->create_body(bs);
    n.shapes.assign(converted::count(n.list.size()), {});
  }
  while (n.next < n.list.size()) {
    const std::size_t slot = converted::post_inc(n.next);
    const auto [tile_key, bi] = converted::at(n.list, slot);
    auto it = tiles_.find(tile_key);
    if (it == tiles_.end() || bi >= converted::present(it->second)->features.buildings.size()) continue;
    converted::at(n.shapes, slot) = building_shape(n.body, converted::at(converted::present(it->second)->features.buildings, bi));
    if (converted::at(n.shapes, slot).valid()) ++n.colliders;
    if (!whole && ++built >= kNearPerStep) return n.next >= n.list.size();
  }
  return true;
}
physics::Shape CityStream::building_shape(physics::Body body, const MapFeatures::Building& b) {
  Earcut earcut;
  std::vector<f64> xy;
  std::vector<u32> holes, tris, idx;
  std::vector<Vec3> pts;
  xy.clear(); holes.clear(); tris.clear(); idx.clear(); pts.clear();
  std::vector<std::vector<Vec2>> rings = b.rings;
  // MAX_VERTICES 64 per ring
  for (auto& ring : rings)
    if (ring.size() > 64) { const std::size_t step = (ring.size() + 63) / 64; std::vector<Vec2> thin; for (std::size_t k = 0; k < ring.size(); k += step) thin.push_back(converted::at(ring, k)); ring = std::move(thin); }
  for (std::size_t r = 0; r < rings.size(); converted::pre_inc(r)) {
    auto& ring = converted::at(rings, r);
    if (ring.size() < 3) continue;
    const f64 a = city_stream_cpp_local::signed_area(ring);
    if (std::fabs(a) < 0.5) continue;
    if ((r == 0) != (a > 0)) std::reverse(ring.begin(), ring.end());  // outer CCW, courtyards CW
    if (r) holes.push_back(static_cast<u32>(xy.size() / 2));
    for (Vec2 p : ring) xy.insert(xy.end(), {p.x, p.y});
    // Walls: quads per edge, outward = right of the edge for CCW outer / CW holes.
    for (std::size_t i = 0; i < ring.size(); converted::pre_inc(i)) {
      const Vec2 p0 = converted::at(ring, i), p1 = converted::at(ring, converted::rem((i + 1), ring.size()));
      const u32 base = static_cast<u32>(pts.size());
      pts.push_back({p0.x, p0.y, b.base});
      pts.push_back({p1.x, p1.y, b.base});
      pts.push_back({p1.x, p1.y, b.top});
      pts.push_back({p0.x, p0.y, b.top});
      idx.insert(idx.end(), {base, base + 1, base + 2, base, base + 2, base + 3});
    }
  }
  if (xy.size() >= 6) {
    earcut.triangulate(xy.data(), static_cast<u32>(xy.size() / 2), holes.data(), static_cast<u32>(holes.size()), tris);
    const u32 base = static_cast<u32>(pts.size());
    for (std::size_t i = 0; i < xy.size() / 2; converted::pre_inc(i)) pts.push_back({static_cast<f32>(converted::at(xy, i * 2)), static_cast<f32>(converted::at(xy, i * 2 + 1)), b.top});
    for (std::size_t i = 0; i + 2 < tris.size(); i += 3) {
      u32 a = base + converted::at(tris, i), c = base + converted::at(tris, i + 1), d = base + converted::at(tris, i + 2);
      if (::converted_SpawnCity__spiel_cpp::cross(converted::at(pts, c) - converted::at(pts, a), converted::at(pts, d) - converted::at(pts, a)).z < 0) std::swap(c, d);
      idx.insert(idx.end(), {a, c, d});
    }
  }
  if (!idx.empty()) {
    physics::ShapeSettings ss;
    ss.kind = physics::ShapeKind::mesh;
    ss.points = Span<const Vec3>(pts.data(), pts.size());
    ss.indices = Span<const u32>(idx.data(), idx.size());
    ss.material.friction = 0.7f;
    ss.material.category_bits = kCatWorld;
    return world_->create_shape(body, ss);
  }
  return {};
}
namespace drone_cpp_local { constexpr f32 kBearingDrag = 1.5e-7f; }
namespace drone_cpp_local { constexpr f32 kMotorYawSign[4] = {-1, 1, -1, 1}; }
namespace drone_cpp_local { constexpr f32 kNavRayMax = 215.0f; }
namespace drone_cpp_local { constexpr f32 kMinClearance = 0.5f, kMaxClearance = 120.0f; }
namespace drone_cpp_local { f32 battery_ocv(f32 soc, f32 cells) {
  const f32 s = clampf(soc, 0, 1);
  return cells * std::fmin(4.2f, 3.2625f + 0.9f * s + 0.0375f * std::tanh((s - 0.12f) * 18));
} }
namespace drone_cpp_local { f32 battery_under_load(f32 ocv, f32 amps, f32 r, f32 cells) {
  return clampf(ocv - std::fmax(0.0f, amps) * r, 3 * cells, 4.2f * cells);
} }
namespace drone_cpp_local { void encode_sbus(const std::array<u16, 16>& ch, std::array<u8, 25>& p) {
  p.fill(0);
  p[0] = 0x0F;
  for (int c = 0; c < 16; converted::pre_inc(c))
    for (int bit = 0; bit < 11; converted::pre_inc(bit))
      if (converted::at(ch, c) & (converted::shl(1u, bit))) {
        const int k = converted::plus(converted::plus(8, converted::times(c, 11)), bit);
        converted::at(p, k / 8) |= static_cast<u8>(converted::shl(1u, (k % 8)));
      }
} }
namespace drone_cpp_local { void put_be16(std::array<u8, 14>& out, u32 at, f32 v) {
  const long r = std::lround(clampf(v, -32767, 32767));
  const u16 u = static_cast<u16>(static_cast<int16_t>(r));
  converted::at(out, at) = static_cast<u8>(u >> 8);
  converted::at(out, at + 1) = static_cast<u8>(u & 0xff);
} }
namespace drone_cpp_local { f32 quat_yaw_deg(Quat q) {
  return std::atan2(2 * (q.w * q.z + q.x * q.y), 1 - 2 * (q.y * q.y + q.z * q.z)) / kDeg;
} }
void Drone::imu_bytes(f32 dt, const BodyState& s, std::array<u8, 14>& out) {
  for (int i = 0; i < 3; converted::pre_inc(i)) {
    converted::at(gyro_bias_, i) += noise_.gaussian() * 0.002f * std::sqrt(dt);
    converted::at(acc_bias_, i) += noise_.gaussian() * 0.00002f * std::sqrt(dt);
  }
  const Vec3 omega_body = to_local(s.rotation, s.angular);
  const Vec3 alpha = (omega_body - prev_omega_body_) * (1.0f / dt);
  prev_omega_body_ = omega_body;
  const Vec3 specific = to_local(s.rotation, world_accel_ - Vec3{0, 0, -kG});
  const Vec3 off{0, 0, 0.008f};
  Vec3 accel = specific + ::converted_SpawnCity__spiel_cpp::cross(alpha, off) + ::converted_SpawnCity__spiel_cpp::cross(omega_body, ::converted_SpawnCity__spiel_cpp::cross(omega_body, off));
  Vec3 gyro = omega_body * (1.0f / kDeg);
  for (int i = 0; i < 3; converted::pre_inc(i)) {
    accel[i] += converted::at(acc_bias_, i) * kG + noise_.gaussian() * 0.0025f * kG;
    gyro[i] += converted::at(gyro_bias_, i) + noise_.gaussian() * 0.035f;
  }
  out[0] = 0;
  out[1] = 0;
  drone_cpp_local::put_be16(out, 2, accel.x / kG * 2048);
  drone_cpp_local::put_be16(out, 4, accel.y / kG * 2048);
  drone_cpp_local::put_be16(out, 6, accel.z / kG * 2048);
  drone_cpp_local::put_be16(out, 8, gyro.x * 16.4f);
  drone_cpp_local::put_be16(out, 10, gyro.y * 16.4f);
  drone_cpp_local::put_be16(out, 12, gyro.z * 16.4f);
}
void Drone::motor_tick(f32 dt, const BodyState& s, f32 altitude, std::array<f32, 4>& thrust_out, std::array<f32, 4>& torque_out) {
  const f32 ocv = drone_cpp_local::battery_ocv(soc_, p_.cells);
  const f32 limit = std::fmin(p_.motor_limit_a, p_.esc_limit_a);
  f32 total = 0;
  for (int pass = 0; pass < 2; converted::pre_inc(pass)) {
    total = 0;
    for (int i = 0; i < 4; converted::pre_inc(i)) {
      const f32 command = clampf((converted::at(pulses_, i) - 1000.0f) / 1000.0f, 0, 1);
      const f32 volts = command * (pass ? vbatt_ : ocv);
      converted::at(current_, i) = clampf((volts - back_emf_ * converted::at(omega_, i)) / p_.R, 0, limit);
      total += converted::at(current_, i);
    }
    if (total > p_.battery_max_a && total > 1e-12f) {
      const f32 k = p_.battery_max_a / total;
      for (f32& c : current_) c *= k;
      total = p_.battery_max_a;
    }
    vbatt_ = drone_cpp_local::battery_under_load(ocv, total, p_.battery_r, p_.cells);
  }
  ibatt_ = total;
  soc_ = clampf(soc_ - total * dt / (p_.capacity_ah * 3600), 0, 1);
  const Vec3 local_v = to_local(s.rotation, s.velocity);
  for (int i = 0; i < 4; converted::pre_inc(i)) {
    const f32 rev = converted::at(omega_, i) / (2 * kPi);
    const f32 prop_torque = p_.Cq * p_.rho * rev * rev * d5_;
    const f32 motor_torque = back_emf_ * converted::at(current_, i);  // Kt = Ke in SI units
    converted::at(motor_torque_, i) = motor_torque;
    converted::at(prop_torque_, i) = prop_torque;
    converted::at(omega_, i) = std::fmax(0.0f, converted::at(omega_, i) + (motor_torque - prop_torque - drone_cpp_local::kBearingDrag * converted::at(omega_, i)) * dt / p_.J);
    const f32 n = converted::at(omega_, i) / (2 * kPi);
    f32 thrust = p_.Ct * p_.rho * n * n * d4_;
    const f32 advance = local_v.z / std::fmax(1.0f, n * p_.prop_d);
    thrust *= clampf(1 - 0.12f * advance, 0.55f, 1.25f);
    thrust *= 1 + p_.ground_effect * std::exp(-altitude / std::fmax(0.02f, 0.75f * p_.prop_d));
    converted::at(thrust_out, i) += thrust;
    converted::at(torque_out, i) += converted::at(drone_cpp_local::kMotorYawSign, i) * motor_torque;
    converted::at(rotor_angle_, i) = std::fmod(converted::at(rotor_angle_, i) + (i % 2 ? -1.0f : 1.0f) * converted::at(omega_, i) * dt, 2 * kPi);
  }
}
void Drone::step(World& world, physics::Body body, f32 h, const DroneSticks& sticks) {
  const BodyState s = read_body(world, body);
  if (have_prev_ && h > 0) world_accel_ = (s.velocity - prev_velocity_) * (1.0f / h);
  prev_velocity_ = s.velocity;
  have_prev_ = true;

  // Rangefinder: a Box3D ray along the body's -Z from just below the frame (groundRange).
  const Vec3 down = s.rotation.rotate({0, 0, -1});
  const f32 vertical = -down.z;
  RayResult range;
  // Like the original's filter (maskBits = COLLISION_TERRAIN) it sees only the fixed world - terrain
  // and buildings: cars, pedestrians, ragdolls, animals and pigeons passing below do not make the
  // altitude hold jump (each moving hit is stepped past).
  if (vertical > 0.55f) {
    Vec3 o = s.position + s.rotation.rotate({0, 0, -0.018f});
    f32 travelled = 0;
    for (int k = 0; k < 6; converted::pre_inc(k)) {
      const physics::RayHit h = world.cast_ray(o, down * (drone_cpp_local::kNavRayMax - travelled), kCatWorld, body);
      if (!h.hit) break;
      const f32 d = h.fraction * (drone_cpp_local::kNavRayMax - travelled);
      if (!h.body.valid() || world.body_type(h.body) == physics::BodyType::fixed) {
        range.hit = true; range.distance = travelled + d; range.point = h.point; range.normal = h.normal;
        break;
      }
      travelled += d + 0.02f;
      o = h.point + down * 0.02f;
      if (travelled >= drone_cpp_local::kNavRayMax) break;
    }
  }
  const bool agl_valid = range.hit && range.distance >= 0.001f;
  const f32 true_agl = agl_valid ? range.distance * vertical : 999.0f;
  // Truth altitude above whatever is straight below (ground effect).
  const RayResult below = cast(world, s.position, {0, 0, -1}, 50.0f, body);
  const f32 altitude = std::fmax(0.001f, below.hit ? below.distance : 50.0f);

  // SBUS channels (simulator.mjs controls()).
  std::array<u16, 16> ch;
  for (u16& c : ch) c = 992;
  auto centered = [](f32 v) { return static_cast<u16>(std::lround(992 + 820 * clampf(v, -1, 1))); };
  ch[0] = centered(sticks.roll);
  ch[1] = centered(sticks.pitch);
  ch[3] = centered(sticks.yaw);
  ch[4] = sticks.arm && !sticks.kill ? 1811 : 172;
  if (sticks.game_mode) {
    ch[2] = 172;
    const f32 clearance = clampf(sticks.clearance, drone_cpp_local::kMinClearance, drone_cpp_local::kMaxClearance);
    ch[5] = static_cast<u16>(std::lround(172 + 1639 * (clearance - drone_cpp_local::kMinClearance) / (drone_cpp_local::kMaxClearance - drone_cpp_local::kMinClearance)));
    ch[6] = 1811;
    ch[7] = centered(sticks.body_pitch);
  } else {
    ch[2] = static_cast<u16>(std::lround(172 + 1639 * clampf(sticks.throttle, 0, 1)));
  }

  const int ticks = std::max(1, static_cast<int>(std::lround(h * 1000.0f)));
  const f32 dt = h / static_cast<f32>(ticks);
  std::array<f32, 4> thrust = {}, yaw_torque = {};
  fc::RuntimeOutput out{};
  for (int t = 0; t < ticks; converted::pre_inc(t)) {
    fc::HardwareFrame hw{};
    now_us_ += static_cast<f64>(dt) * 1e6;
    hw.now_us = static_cast<uint64_t>(converted::fits<unsigned long>(now_us_));
    hw.dt_us = static_cast<uint32_t>(std::lround(dt * 1e6f));
    imu_bytes(dt, s, hw.imu_registers);
    hw.imu_present = true;
    sbus_elapsed_ += dt;
    if (sbus_elapsed_ >= 0.01f) {
      sbus_elapsed_ -= 0.01f;
      drone_cpp_local::encode_sbus(ch, hw.sbus_frame);
      hw.sbus_present = true;
    }
    nav_elapsed_ += dt;
    if (nav_elapsed_ >= 0.01f) {
      nav_elapsed_ -= 0.01f;
      for (int i = 0; i < 3; converted::pre_inc(i)) {
        const f32 measured = s.velocity[i] + nav_noise_.gaussian() * 0.025f;
        nav_filtered_[i] += 0.42f * (measured - nav_filtered_[i]);
      }
      f32 agl = 0;
      if (agl_valid) agl = std::fmax(0.0f, range.distance + nav_noise_.gaussian() * 0.004f) * vertical;
      const f32 heading = drone_cpp_local::quat_yaw_deg(s.rotation) + heading_noise_.gaussian() * 0.12f;
      hw.navigation_frame = hwcontract::encode_navigation_wire(nav_seq_++, nav_filtered_.x, nav_filtered_.y, nav_filtered_.z, agl, true, agl_valid,
                                                               heading, true);
      hw.navigation_present = true;
    }
    if (reset_flag_) { fw_.reset(); reset_flag_ = false; }
    out = fw_.step(hw);
    for (int i = 0; i < 4; converted::pre_inc(i)) converted::at(pulses_, i) = sticks.kill ? 1000 : converted::at(out.motor_us, i);
    motor_tick(dt, s, altitude, thrust, yaw_torque);
  }

  // A latched firmware fault on a disarmed airframe at rest (calibration while it was still
  // settling, a crash): the pilot power-cycles it, as with the real quad - the FC boots and
  // calibrates again.
  if (out.fault != fc::kFaultNone && !out.armed && ::converted_SpawnCity__spiel_cpp::length(s.velocity) < 0.05f && ::converted_SpawnCity__spiel_cpp::length(s.angular) < 0.05f) reset_flag_ = true;

  // Parked (motors stopped, at rest for 0.5 s): no forces to apply.
  bool commanded = false;
  for (int i = 0; i < 4; converted::pre_inc(i)) commanded |= converted::at(pulses_, i) > 1000 || converted::at(omega_, i) > 1e-3f;
  if (commanded) parked_steps_ = 0, parked_ = false;
  else if (::converted_SpawnCity__spiel_cpp::length(s.velocity) < 2e-3f && ::converted_SpawnCity__spiel_cpp::length(s.angular) < 2e-3f) parked_ = ++parked_steps_ > static_cast<u32>(converted::fits<unsigned int>(0.5f / h));
  else parked_steps_ = 0, parked_ = false;

  const f32 inv = 1.0f / static_cast<f32>(ticks);
  if (commanded) {
    for (int i = 0; i < 4; converted::pre_inc(i)) {
      world.apply_force(body, s.rotation.rotate({0, 0, converted::at(thrust, i) * inv}), s.position + s.rotation.rotate(converted::at(motor_pos_, i)));
      world.apply_torque(body, s.rotation.rotate({0, 0, converted::at(yaw_torque, i) * inv}));
    }
  }
  const Vec3 rel = to_local(s.rotation, s.velocity - p_.wind);
  const f32 hs = std::hypot(rel.x, rel.y);
  const Vec3 drag{-0.5f * p_.rho * cdA_.x * rel.x * hs, -0.5f * p_.rho * cdA_.y * rel.y * hs, -0.5f * p_.rho * cdA_.z * rel.z * std::fabs(rel.z)};
  world.apply_force_to_center(body, s.rotation.rotate(drag));
  const Vec3 w = to_local(s.rotation, s.angular);
  world.apply_torque(body, s.rotation.rotate({-0.0012f * w.x * std::fabs(w.x), -0.0012f * w.y * std::fabs(w.y), -0.0012f * w.z * std::fabs(w.z)}));

  tele_.state = out.state;
  tele_.armed = out.armed;
  tele_.calibrating = (out.state & fc::kStateCalibrating) != 0;
  tele_.fault = (out.state & fc::kStateFault) != 0;
  tele_.game = (out.state & fc::kStateGameMode) != 0;
  tele_.nav_valid = (out.state & fc::kStateNavigationValid) != 0;
  for (int i = 0; i < 4; converted::pre_inc(i)) { converted::at(tele_.pulses, i) = converted::at(pulses_, i); converted::at(tele_.omega, i) = converted::at(omega_, i); converted::at(tele_.motor_torque, i) = converted::at(motor_torque_, i); converted::at(tele_.prop_torque, i) = converted::at(prop_torque_, i); }
  tele_.battery_v = vbatt_;
  tele_.battery_soc = soc_;
  tele_.current_a = ibatt_;
  tele_.agl = agl_valid ? true_agl : -1;
  tele_.speed = ::converted_SpawnCity__spiel_cpp::length(s.velocity);
  tele_.vz = s.velocity.z;
  for (int i = 0; i < 3; converted::pre_inc(i)) converted::at(tele_.attitude_deg, i) = converted::at(out.attitude_cdeg, i) * 0.01f;
}
